"""Lay the voice-over lines on the film's clock and write src/vo.js (start/end of each line, Chinese text, English subtitle).
Run from anywhere: python3 audio/vo_timeline.py. Reads vo/lines.json and vo/dur.json."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
L = json.load(open(os.path.join(ROOT, 'vo/lines.json'))); D = json.load(open(os.path.join(ROOT, 'vo/dur.json')))
EN = [
  'You send a friend a cat photo. Ding, it arrives right away.',
  "But the photo didn't fly straight there.",
  'The moment you hit send, step one: make it smaller.',
  'The original is too big and slow to send, so the app quietly compresses it: smaller, yet it looks about the same.',
  'Next, the photo reaches stop two: the server.',
  "That's the chat app's relay station in the cloud. The photo waits here to be picked up.",
  'Only then comes step three: the notification.',
  'The server taps your friend\'s phone: "Hey, a photo for you."',
  "That's when the phone goes ding.",
  "After the notification, your friend's phone goes to the server and fetches the photo.",
  'So on a slow connection, you see it blurry for a moment, then suddenly sharp.',
  'Behind that one ding is a silent relay.',
  'Unless you ticked "Original", what your friend gets is just a compressed copy of the cat.',
  'The real original has been on your phone all along.',
]
LEAD = .8
GAP = [.4, .5, .3, .6, .3, .6, .3, .3, .6, .3, .6, .35, .3, .3]
TARGET = 59.95   # the film's length is fixed; whatever the last line leaves is the closing shot
t = LEAD; out = []
for i, l in enumerate(L):
    d = D[l['id']]; out.append({'id': l['id'], 't0': round(t, 3), 't1': round(t + d, 3), 'zh': l['text'], 'en': EN[i]}); t += d + GAP[i]
dur = TARGET; CREDIT = TARGET - t
js = '// Voice-over lines on the film clock (generated by audio/vo_timeline.py from vo/). t0/t1 = speech start/end.\n'
js += f'export const DUR = {dur};\nexport const CREDIT_T = {round(t, 2)};\nexport const VO = ' + json.dumps(out, ensure_ascii=False, indent=1) + ';\n'
open(os.path.join(ROOT, 'src/vo.js'), 'w').write(js)
json.dump({'dur': dur, 'lines': out}, open(os.path.join(ROOT, 'vo/timeline.json'), 'w'), ensure_ascii=False, indent=1)
print('dur', dur, 'credit at', round(t, 2))
for o in out: print(o['id'], o['t0'], o['t1'], o['zh'])
